package servicio;
import java.math.RoundingMode;import java.time.LocalDateTime;import negocio.*;
public class OrdenPagoService {
 public OrdenPago preparar(OrdenPago o){if(o==null)throw new IllegalArgumentException("La orden es obligatoria.");if(o.getReservaId()<=0)throw new IllegalArgumentException("La reserva es obligatoria.");if(o.getImporte()==null||o.getImporte().signum()<=0)throw new IllegalArgumentException("El importe debe ser mayor que cero.");if(o.getClaveIdempotencia()==null||o.getClaveIdempotencia().isBlank())throw new IllegalArgumentException("La clave de idempotencia es obligatoria.");if(o.getProveedor()==null||o.getMetodo()==null)throw new IllegalArgumentException("El proveedor y el método son obligatorios.");o.setImporte(o.getImporte().setScale(2,RoundingMode.HALF_UP));o.setMoneda(o.getMoneda()==null||o.getMoneda().isBlank()?"ARS":o.getMoneda().trim().toUpperCase());o.setClaveIdempotencia(o.getClaveIdempotencia().trim());if(o.getFechaCreacion()==null)o.setFechaCreacion(LocalDateTime.now());return o;}
 public void cambiarEstado(OrdenPago o,EstadoOrdenPago siguiente){if(o==null||o.getEstado()==null)throw new IllegalArgumentException("La orden y su estado son obligatorios.");if(!o.getEstado().puedeCambiarA(siguiente))throw new IllegalStateException("Transición de pago no permitida: "+o.getEstado()+" -> "+siguiente);o.setEstado(siguiente);if(siguiente==EstadoOrdenPago.APROBADA)o.setFechaAprobacion(LocalDateTime.now());}
 public boolean debeEsperarVerificacionManual(OrdenPago o){return o!=null&&o.getMetodo()==MetodoOrdenPago.TRANSFERENCIA_MANUAL&&o.getEstado()==EstadoOrdenPago.ESPERANDO_VERIFICACION;}
}
